  check(threw(() => applyRoomAction(r, 'b', 'penalty', {})) && (applyRoomAction(r, 'b', 'penalty', { target: 'c' }), r.shared.phase === 'gameover'),
    'monkey: a penalty after the end is refused, or dropped quietly when it names its player');
